package android.provider;import android.net.Uri;import android.content.ContentResolver;import android.app.PendingIntent;public class MediaStore{public static boolean consent;public static Uri getMediaUri(Object a,Uri u){return u.getAuthority().equals("media")?u:null;}public static Uri getDocumentUri(Object a,Uri u){return null;}public static PendingIntent createDeleteRequest(ContentResolver r,java.util.Collection<Uri> u){if(!consent)throw new IllegalArgumentException("nonmedia");return new PendingIntent();}}
